def rows(name):
    with (DB/name).open(encoding="utf-8",newline="") as f:return list(csv.DictReader(f))
def count(rows_, key):return dict(sorted(Counter((r.get(key,"") if r.get(key,"")!="" else "<null>") for r in rows_).items()))
def write_csv(path, data, fields):
    with path.open("w",encoding="utf-8",newline="") as f:
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(data)
def git(*args):return subprocess.check_output(["git",*args],cwd=ROOT,text=True,encoding="utf-8",errors="replace").strip()
def brief(r):
    keys=["geometry_id","geometry_hash","candidate_id_primary","candidate_aliases","topology_family","N","M","H_nm","L_nm","C_nm","added_defect_thickness_nm","effective_central_L_thickness_nm","physical_layer_count","total_thickness_nm","is_nominal_geometry","parent_nominal_geometry_id","provenance_count","quality_status"]
    return {k:r.get(k,"") for k in keys}

def main():
    manifest=json.loads((DB/"database_manifest.json").read_text(encoding="utf-8"));schema=json.loads((DB/"schema.json").read_text(encoding="utf-8"));split_audit=json.loads((DB/"split_audit.json").read_text(encoding="utf-8"));quality=json.loads((DB/"quality_audit.json").read_text(encoding="utf-8"))
    geo=rows("geometry_master.csv");tmm=rows("tmm_nominal_metrics.csv");tol=rows("tolerance_samples.csv");fdtd=rows("fdtd_validation.csv");spl=rows("split_assignments.csv");prov=rows("provenance_links.csv");labels=rows("label_dictionary.csv")
