    false_dist={"topology":count([by_gid[x["geometry_id"]] for x in tmm_false],"topology_family"),"tmm_source":count(tmm_false,"tmm_source_id"),"fidelity":count(tmm_false,"tmm_fidelity"),"split":count(tmm_false,"split"),"parent_nominal_geometry_id_blank":sum(not x["parent_nominal_geometry_id"] for x in tmm_false),"parent_nominal_geometry_id_nonblank":sum(bool(x["parent_nominal_geometry_id"]) for x in tmm_false),"provenance_source_counts":dict(false_prov)}
    split_tmm=[x for x in spl if x.get("record_id") in tmm_by_gid or x.get("source_stage") in ("coarse","refined")]
