    trace={"builder":"scripts/build_mdc_ml_database_v1.py","introducing_commit":git("log","--format=%H","-1","--","scripts/build_mdc_ml_database_v1.py"),"is_nominal_write":{"line":77,"condition":"candidate in NOMINAL_IDS","nominal_ids_line":83,"nominal_ids":["EX_N3_L79_H45_C156","ZL1_N3_M3_L78_H46","ZL1_N3_M3_L79_H44_C316","BARE_GAN_AIR_450_XDIPOLE"]},"canonical_tmm":{"function":"build_tmm","lines":"109-119","input":"coarse metrics_all.csv plus refined metrics_refined.csv","canonicalization":"chosen[geometry_hash]; refined supersedes coarse","no_is_nominal_filter":True},"tolerance":{"function":"build_tolerance","lines":"121-128","separate_table":"tolerance_samples.csv","usable_for_training":"false"},"split":{"lines":"172-201","strategy":"grouped_parent_geometry_v1 constraint graph","tmm_assignment":"line 195, one assignment per canonical TMM record","tolerance_assignment":"line 196, separate rows usable_for_training=false","fdtd_assignment":"line 197, external_high_fidelity_validation"},"history":git("log","--oneline","--follow","--","scripts/build_mdc_ml_database_v1.py").splitlines()}
    summary={"audit_name":"MDC_DATABASE_NOMINAL_SEMANTIC_AUDIT_V1","head":git("rev-parse","HEAD"),"database_manifest":manifest,"schema_version":schema.get("schema_version"),"table_counts":{"geometry_master_rows":len(geo),"geometry_master_unique_geometry_hashes":len(geo_hashes),"tmm_nominal_rows":len(tmm),"tmm_nominal_unique_geometry_hashes":len(tmm_hashes),"tolerance_rows":len(tol),"fdtd_rows":len(fdtd)},"hash_join":{"intersection":len(tmm_hashes&geo_hashes),"tmm_left_missing_from_geometry":len(tmm_hashes-geo_hashes),"geometry_right_not_in_tmm":len(geo_hashes-tmm_hashes),"tmm_duplicate_hash_rows":len(tmm)-len(tmm_hashes),"tmm_tolerance_hash_overlap":len(tmm_hashes&tol_hashes),"tmm_fdtd_hash_overlap":len(tmm_hashes&fdtd_hashes)},"is_nominal_geometry_all_geometry_master":count(geo,"is_nominal_geometry"),"reference_marker_scope":{"geometry_master_true_rows":len(geo_true),"geometry_master_true_rows_with_tolerance_provenance":true_with_tolerance},"is_nominal_geometry_among_tmm_join":count(joined,"is_nominal_geometry"),"tmm_join":{"id_matched":sum(x["id_join_status"]=="matched" for x in joined),"hash_matched":sum(x["hash_join_status"]=="matched" for x in joined),"true_rows":true_identity,"false_distribution":false_dist},"equivalent_fields":eq_fields,"tolerance_boundary":{"tmm_source_distribution":count(tmm,"source_id"),"tmm_simulation_method_distribution":count(tmm,"simulation_method"),"tmm_usable_distribution":count(tmm,"usable_for_training"),"tolerance_usable_distribution":count(tol,"usable_for_training"),"tmm_record_id_overlap_tolerance_sample_id":len(tmm_ids & {r["sample_id"] for r in tol}),"tmm_rows_with_tolerance_source_id":sum("tolerance" in r.get("source_id","").lower() for r in tmm)},"split_trace":{"tmm_records_present":len(split_tmm),"tmm_records_missing_from_split":len(tmm_ids-{r["record_id"] for r in split_tmm}),"extra_split_records_matching_tmm":len({r["record_id"] for r in split_tmm}-tmm_ids),"tmm_split_counts":count(split_tmm,"split"),"tmm_source_stage_counts":count(split_tmm,"source_stage"),"global_split_audit":split_audit},"label_dictionary_names":[r["label_name"] for r in labels],"quality_audit":quality,"generation_trace":trace,"root_cause":{"classification":"B intended, C implementation defect","finding":"is_nominal_geometry is assigned by candidate-id membership in a four-item reference list, not by simulation/sample role. build_tmm independently canonically emits all 2688 coarse/refined TMM scan records without filtering this flag. The field therefore means reference-candidate identity only when candidate naming is reliable; it also propagates to tolerance geometries carrying a reference candidate_id, so it is not a safe global nominal-sample flag."}}
    (OUT/"nominal_identity_summary.json").write_text(json.dumps(summary,indent=2),encoding="utf-8")
    lines=["# MDC database nominal semantic audit v1","",f"HEAD: `{summary['head']}`. Database/schema: {manifest['database_version']}/{schema.get('schema_version')}.","","## Finding","", "`is_nominal_geometry` is not the canonical definition of a nominal TMM sample. The builder writes it as `candidate in NOMINAL_IDS` (line 77), while `build_tmm` independently canonicalizes every coarse/refined scan geometry by geometry hash (lines 109-119) and writes all 2,688 rows to `tmm_nominal_metrics.csv` without consulting that flag.","", "The field was intended as a curated reference-candidate marker (B), but its implementation also applies to tolerance geometries that retain a reference candidate id. Therefore it is unsafe as a global physical nominal/perturbation predicate (C implementation defect).", "", "## Counts","", f"- geometry_master: {len(geo)} rows / {len(geo_hashes)} unique hashes.",f"- tmm_nominal_metrics: {len(tmm)} rows / {len(tmm_hashes)} unique hashes.",f"- TMM→geometry hash intersection: {len(tmm_hashes&geo_hashes)}; TMM left missing: {len(tmm_hashes-geo_hashes)}; geometry hashes not in TMM: {len(geo_hashes-tmm_hashes)}.",f"- `is_nominal_geometry` among all geometry rows: {count(geo,'is_nominal_geometry')}; among the canonical TMM join: {count(joined,'is_nominal_geometry')}.","", "## Two true canonical-TMM rows","", "| candidate | topology | geometry_id | H/L/C-or-center | layers / total nm | source / split |","|---|---|---|---|---|---|"]
    for r in true_identity: lines.append(f"| {r['candidate_id_primary']} | {r['topology_family']} | {r['geometry_id']} | H={r['H_nm']}, L={r['L_nm']}, C={r['C_nm'] or '-'}, center={r['effective_central_L_thickness_nm'] or '-'} | {r['physical_layer_count']} / {r['total_thickness_nm']} | {r['tmm_source_id']} / {r['split']} |")
    lines += ["", "## Tolerance and split boundary","", f"- Canonical TMM sources: {count(tmm,'source_id')}; all carry simulation_method TMM and usable_for_training true.", f"- Tolerance sources are stored only in tolerance_samples.csv ({len(tol)} rows), with usable_for_training false. TMM record-id overlap with tolerance sample IDs: 0; TMM rows with tolerance source id: 0.", f"- Existing split contains all {len(split_tmm)} canonical TMM records: {count(split_tmm,'split')}. Assignment is direct per TMM record, but its constraint graph also includes tolerance parent links to prevent geometry leakage.", "", "## Minimal repair options (not implemented)", "", "1. Recommended C — make `tmm_nominal_metrics` the canonical nominal-sample fact table in task views; use geometry_master only for geometry joins. No reinterpretation of existing `is_nominal_geometry`; no database-v1 rebuild required for a task view. Add explicit join semantics to a future schema/report revision.", "2. A — retain the field as curated-reference identity and introduce `sample_role` / `is_nominal_tmm_sample` in a v1.1 database rebuild. This preserves existing field semantics; requires schema version bump and database regeneration, but does not change tolerance/FDTD boundaries.", "3. B — regenerate `is_nominal_geometry` for all 2,688 canonical TMM hashes. Not recommended because it changes the field's current curated-reference meaning and still fails to distinguish TMM nominal rows from tolerance geometries sharing candidate identifiers; requires a schema bump and rebuild.", "", "## Recommendation","", "Use `tmm_nominal_metrics` + its `simulation_method=TMM`, `usable_for_training=true`, and canonical record identity as the nominal training universe. Do not filter on `geometry_master.is_nominal_geometry`. Before future release, add an explicit sample-role field and correct the reference-marker name."]
    REPORT.parent.mkdir(parents=True,exist_ok=True);REPORT.write_text("\n".join(lines)+"\n",encoding="utf-8")
